const html = String($input.first().json.data ?? "");

// Extract links from the search page HTML.
const matches = html.matchAll(
  /href\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/gi
);

const hrefs = [...matches].map(m =>
  (m[1] ?? m[2] ?? m[3]).replace(/&amp;/g, "&").trim()
);

const uniqueUrls = new Set();

for (const href of hrefs) {
  // Keep only individual vehicle detail pages.
  if (!/\/usedcar\/detail\/[^/?#]+/i.test(href)) {
    continue;
  }

  let fullUrl;

  if (/^https?:\/\//i.test(href)) {
    fullUrl = href;
  } else if (href.startsWith("//")) {
    fullUrl = "https:" + href;
  } else if (href.startsWith("/")) {
    fullUrl = "https://kuruma-ex.jp" + href;
  } else {
    continue;
  }

  // Only allow the intended website.
  if (!/^https:\/\/kuruma-ex\.jp\/usedcar\/detail\//i.test(fullUrl)) {
    continue;
  }

  uniqueUrls.add(fullUrl);
}

const results = [...uniqueUrls].slice(0, 3);

if (results.length === 0) {
  return [{
    json: {
      error: "No vehicle URLs returned",
      hrefCount: hrefs.length,
      matchingLinks: hrefs.filter(
        href => /\/usedcar\/detail\//i.test(href)
      ).slice(0, 1)
    }
  }];
}

return results.map(detailUrl => ({
  json: { detailUrl }
}));

const items = $input.all();

function decodeHtml(s) {
  return s
    .replace(/&nbsp;|&#160;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&yen;/gi, "¥")
    .replace(/&#(\d+);/g, (_, n) =>
      String.fromCodePoint(Number(n))
    )
    .replace(/&#x([0-9a-f]+);/gi, (_, n) =>
      String.fromCodePoint(parseInt(n, 16))
    );
}

function extractVehicle(item) {
  const html = String(item.json.data ?? "");

  const text = decodeHtml(
    html
      .replace(/<script\b[\s\S]*?<\/script>/gi, " ")
      .replace(/<style\b[\s\S]*?<\/style>/gi, " ")
      .replace(/<[^>]+>/g, " ")
  ).replace(/\s+/g, " ").trim();

  const titleMatch = html.match(
    /<title[^>]*>([\s\S]*?)<\/title>/i
  );

  const vehicleTitle = titleMatch
    ? decodeHtml(titleMatch[1])
        .replace(/<[^>]*>/g, "")
        .trim()
    : "";

  const totalMatch =
    text.match(/支払総額\s*(?:（税込）|\(税込\))?\s*(?:は|[:：])?\s*([0-9][0-9,.]*)\s*万円/i) ||
    text.match(/支払総額[^0-9]{0,35}([0-9][0-9,.]*)\s*万円/i);

  const totalPaymentManYen = totalMatch
    ? Number(totalMatch[1].replace(/,/g, ""))
    : null;

  const totalPaymentJPY = totalPaymentManYen === null
    ? null
    : Math.round(totalPaymentManYen * 10000);

  const yearMatch =
    text.match(/年式\s*[:：]?\s*(20\d{2})年?/i) ||
    text.match(/(?:^|\s)(20\d{2})年\s*式/);

  const modelYear = yearMatch
    ? Number(yearMatch[1] ?? yearMatch[2])
    : null;

  const mileageMatch = text.match(
    /走行距離\s*[:：]?\s*([0-9][0-9,]*)\s*(?:km|Ｋｍ|キロメートル)/i
  );

  const mileageKm = mileageMatch
    ? Number(mileageMatch[1].replace(/,/g, ""))
    : null;

  const repairMatch = text.match(
    /修復歴\s*[:：]?\s*(あり|なし|有|無)/
  );

  const repairHistory = repairMatch
    ? repairMatch[1]
    : null;

  const canonicalMatch =
    html.match(/<link\b[^>]*href=["']([^"']+)["'][^>]*rel=["']canonical["']/i) ||
    html.match(/<link\b[^>]*rel=["']canonical["'][^>]*href=["']([^"']+)["']/i);

  const detailUrl = canonicalMatch
    ? canonicalMatch[1]
    : null;

  const missingFields = [];

  if (totalPaymentJPY === null) missingFields.push("totalPaymentJPY");
  if (modelYear === null) missingFields.push("modelYear");
  if (mileageKm === null) missingFields.push("mileageKm");
  if (repairHistory === null) missingFields.push("repairHistory");

  return {
    json: {
      vehicleTitle,
      detailUrl,
      totalPaymentJPY,
      totalPaymentManYen,
      modelYear,
      mileageKm,
      repairHistory,
      extractionStatus: missingFields.length === 0 ? "OK" : "Partial",
      missingFields
    }
  };
}

return items.map(extractVehicle);

const items = $input.all();

const brandMap = [
  ["メルセデス・ベンツ", "Mercedes-Benz"],
  ["メルセデスベンツ", "Mercedes-Benz"],
  ["スズキ", "Suzuki"],
  ["トヨタ", "Toyota"],
  ["ホンダ", "Honda"],
  ["ダイハツ", "Daihatsu"],
  ["日産", "Nissan"],
  ["ニッサン", "Nissan"],
  ["マツダ", "Mazda"],
  ["スバル", "Subaru"],
  ["三菱", "Mitsubishi"],
  ["レクサス", "Lexus"],
  ["いすゞ", "Isuzu"],
  ["光岡", "Mitsuoka"],
  ["BMW", "BMW"],
  ["ＢＭＷ", "BMW"],
  ["MINI", "MINI"]
];

const prefectures = [
  "北海道", "青森県", "岩手県", "宮城県", "秋田県",
  "山形県", "福島県", "茨城県", "栃木県", "群馬県",
  "埼玉県", "千葉県", "東京都", "神奈川県", "新潟県",
  "富山県", "石川県", "福井県", "山梨県", "長野県",
  "岐阜県", "静岡県", "愛知県", "三重県", "滋賀県",
  "京都府", "大阪府", "兵庫県", "奈良県", "和歌山県",
  "鳥取県", "島根県", "岡山県", "広島県", "山口県",
  "徳島県", "香川県", "愛媛県", "高知県", "福岡県",
  "佐賀県", "長崎県", "熊本県", "大分県", "宮崎県",
  "鹿児島県", "沖縄県"
];

function formatYear(year) {
  if (!year) return "";

  if (year >= 2019) return `${year}年(令和${year - 2018}年)`;
  if (year >= 1989) return `${year}年(平成${year - 1988}年)`;
  if (year >= 1926) return `${year}年(昭和${year - 1925}年)`;

  return `${year}年`;
}

function formatMileage(km) {
  if (km == null || km === "") return "";

  const value = Number(km);
  if (!Number.isFinite(value)) return "";

  if (value >= 10000) {
    const man = (value / 10000).toFixed(1).replace(/\.0$/, "");
    return `${man}万km`;
  }

  return `${value.toLocaleString("en-US")}km`;
}

return items.map(item => {
  const data = item.json;

  const rawTitle = String(data.vehicleTitle ?? "").trim();

  // Remove the listing description and dealer information
  // appended to the page title.
  const title = rawTitle
    .split(/中古車情報/i)[0]
    .replace(/[|｜\s]+$/, "")
    .trim();

  const brandEntry = brandMap.find(([jp]) =>
    rawTitle.toUpperCase().startsWith(jp.toUpperCase())
  );

  const brand = brandEntry
    ? brandEntry[1]
    : "";

  const price = data.totalPaymentManYen == null
    ? ""
    : `${Number(data.totalPaymentManYen).toLocaleString(
        "en-US",
        { maximumFractionDigits: 1 }
      )}万円`;

  const salesArea =
    prefectures.find(pref => rawTitle.includes(pref)) ?? "";

  return {
    json: {
      "Brand": brand,
      "Title": title,
      "URL": data.detailUrl ?? "",
      "Price": price,
      "Mileage": formatMileage(data.mileageKm),
      "ModelYear": formatYear(data.modelYear),
      "Repair History": data.repairHistory ?? "",
      "Sales Area": salesArea
    }
  };
});
